"""Write data to a text file.

    Args:
        path (str): Full path to file
        data (str): File text

    Returns:
        int: Number of characters written
    """
def write(path: Any, data: Any) -> object {
    with open(path, 'w') as handle {
        return handle.write(data);
    }
}

